<script setup lang="ts">
const supabase=useSupabaseClient(); const email=ref(''); const loading=ref(false); const error=ref(''); const message=ref('')
async function sendReset(){loading.value=true;error.value='';message.value='';const redirectTo=`${window.location.origin}/host/reset-password`;const {error:e}=await supabase.auth.resetPasswordForEmail(email.value.trim(),{redirectTo});loading.value=false;if(e)return error.value=e.message;message.value='If that email belongs to a host account, a password reset link has been sent.'}
</script>
<template><main class="neon-page grid place-items-center px-4 py-10"><div class="w-full max-w-md"><NuxtLink to="/"><img src="/kc-jukebox-logo.png" class="neon-logo max-w-[210px]" alt="KC Jukebox"></NuxtLink><section class="neon-card mt-5 p-7 sm:p-8"><div class="text-center"><div class="neon-kicker">Host Recovery</div><h1 class="neon-title mt-2 text-3xl">Reset Password</h1><p class="mt-2 text-sm text-slate-500">We’ll email you a secure reset link.</p></div><form class="mt-7 space-y-4" @submit.prevent="sendReset"><div><label class="mb-2 block text-sm font-bold text-slate-300">Email address</label><input v-model="email" class="neon-input" type="email" autocomplete="email" required></div><div v-if="error" class="rounded-xl border border-red-500/30 bg-red-500/10 p-3 text-sm text-red-300">{{error}}</div><div v-if="message" class="rounded-xl border border-green-500/30 bg-green-500/10 p-3 text-sm text-green-300">{{message}}</div><button class="neon-btn w-full" :disabled="loading">{{loading?'Sending…':'Send Reset Link'}}</button></form><p class="mt-6 text-center text-sm text-slate-500"><NuxtLink to="/host/login" class="font-bold text-cyan-400">Back to sign in</NuxtLink></p></section></div></main></template>
